const { execSync } = require('child_process');

const items = $input.all();
for (const item of items) {
  const json = item.json;
  const scriptPath = "c:\\Users\\manas\\OneDrive\\Desktop\\n8n\\append_to_excel.py";
  const b64 = Buffer.from(JSON.stringify(json)).toString('base64');
  execSync(`python "${scriptPath}" "${b64}"`);
}

return items;

const item = $input.item.json;
const req = item.body || item.data || item;

const subject = (req.subject || req.Subject || '').toString().trim();
const classGrade = (req.classGrade || req.grade || req['Class/Grade'] || req.Class || '').toString().trim();
const topic = (req.topic || req.chapter || req.topicChapter || req['Topic/Chapter'] || '').toString().trim();

const numPeriodsRaw = req.numberOfPeriods || req.periods || req['Number of Periods'];
const durPeriodRaw = req.durationPerPeriod || req.duration || req['Duration per Period'];

const numberOfPeriods = parseInt(numPeriodsRaw, 10);
const durationPerPeriod = parseInt(durPeriodRaw, 10);

let learningObjectives = req.learningObjectives || req.objectives || req['Learning Objectives'];
if (Array.isArray(learningObjectives)) {
  learningObjectives = learningObjectives.join('\n- ');
} else {
  learningObjectives = (learningObjectives || '').toString().trim();
}

const missingFields = [];
if (!subject) missingFields.push('Subject');
if (!classGrade) missingFields.push('Class/Grade');
if (!topic) missingFields.push('Topic/Chapter');
if (isNaN(numberOfPeriods) || numberOfPeriods <= 0) missingFields.push('Number of Periods (must be a positive number)');
if (isNaN(durationPerPeriod) || durationPerPeriod <= 0) missingFields.push('Duration per Period (must be a positive number)');
if (!learningObjectives) missingFields.push('Learning Objectives');

if (missingFields.length > 0) {
  return {
    isValid: false,
    statusCode: 400,
    error: 'Validation Error',
    message: `Missing or invalid required fields: ${missingFields.join(', ')}`,
    missingFields: missingFields
  };
}

const today = new Date().toISOString().split('T')[0];
const normalized = {
  teacherName: (req.teacherName || req['Teacher Name'] || 'Teacher').toString().trim(),
  schoolName: (req.schoolName || req['School/Institute Name'] || 'School / Institution').toString().trim(),
  subject,
  classGrade,
  board: (req.board || req.curriculum || req['Board/Curriculum'] || 'Standard Curriculum').toString().trim(),
  topic,
  numberOfPeriods,
  durationPerPeriod,
  totalDurationMinutes: numberOfPeriods * durationPerPeriod,
  lessonDate: (req.lessonDate || req.date || req['Lesson Date'] || today).toString().trim(),
  learningLevel: (req.learningLevel || req.ageGroup || req['Learning Level/Age Group'] || 'Grade Level Standard').toString().trim(),
  learningObjectives,
  prerequisiteKnowledge: (req.prerequisiteKnowledge || req['Prerequisite Knowledge'] || 'Standard grade-appropriate foundational knowledge').toString().trim(),
  teachingMethod: (req.teachingMethod || req.pedagogy || req['Teaching Method/Preferred Pedagogy'] || 'Interactive, Student-Centered & Scaffolded Instruction').toString().trim(),
  availableResources: (req.availableResources || req['Available Resources'] || 'Whiteboard, textbook, digital projection').toString().trim(),
  classroomType: (req.classroomType || req['Classroom Type'] || 'Standard Classroom Setup').toString().trim(),
  studentCount: (req.studentCount || req['Student Count'] || '30-40 students').toString().trim(),
  specialLearningNeeds: (req.specialLearningNeeds || req['Special Learning Needs / Differentiation Notes'] || 'Differentiated tasks for diverse learning needs').toString().trim(),
  homeworkRequirement: (req.homeworkRequirement || req['Homework Requirement'] || 'Practice questions and concept application').toString().trim(),
  assessmentPreference: (req.assessmentPreference || req['Assessment Preference'] || 'Formative checks, oral response & exit tickets').toString().trim(),
  language: (req.language || req['Language of Instruction'] || 'English').toString().trim(),
  additionalInstructions: (req.additionalInstructions || req['Additional Instructions'] || 'None').toString().trim()
};

return {
  isValid: true,
  normalized
};

