const COURSES_API = 'https://6a7db27df8b2ed99ca4ea916.mockapi.io/electronicsapi/courses_batches';
try {
  const response = await fetch(COURSES_API);
  if (!response.ok) {
    return JSON.stringify({ success: false, error: 'Courses API returned error: ' + response.status });
  }
  let courses = await response.json();
  const input = typeof query !== 'undefined' ? query : (typeof $input !== 'undefined' && $input.item && $input.item.json ? $input.item.json : {});

  const q = (input.query || '').toLowerCase().trim();
  const category = (input.category || '').toLowerCase().trim();
  const maxFees = input.maxFees !== undefined ? Number(input.maxFees) : null;
  const mode = (input.mode || '').toLowerCase().trim();
  const timing = (input.timing || '').toLowerCase().trim();
  const duration = (input.duration || '').toLowerCase().trim();

  if (q) {
    courses = courses.filter(c => 
      (c.courseName && c.courseName.toLowerCase().includes(q)) ||
      (c.category && c.category.toLowerCase().includes(q)) ||
      (c.trainer && c.trainer.toLowerCase().includes(q))
    );
  }
  if (category) {
    courses = courses.filter(c => c.category && c.category.toLowerCase().includes(category));
  }
  if (maxFees !== null && !isNaN(maxFees)) {
    courses = courses.filter(c => Number(c.fees) <= maxFees);
  }
  if (mode) {
    courses = courses.filter(c => c.mode && c.mode.toLowerCase() === mode);
  }
  if (duration) {
    courses = courses.filter(c => c.duration && c.duration.toLowerCase().includes(duration));
  }
  if (timing) {
    courses = courses.filter(c => {
      if (!c.batchTime) return false;
      const bt = c.batchTime.toLowerCase();
      if (timing === 'evening') return bt.includes('pm') && (bt.includes('4:') || bt.includes('5:') || bt.includes('6:') || bt.includes('7:') || bt.includes('8:'));
      if (timing === 'morning') return bt.includes('am') || bt.includes('8:') || bt.includes('9:') || bt.includes('10:') || bt.includes('11:');
      if (timing === 'afternoon') return (bt.includes('12:') || bt.includes('1:') || bt.includes('2:') || bt.includes('3:')) && bt.includes('pm');
      return bt.includes(timing);
    });
  }
  if (input.onlyAvailableSeats) {
    courses = courses.filter(c => Number(c.seatsAvailable) > 0 && c.status === 'Active');
  }

  return JSON.stringify({
    success: true,
    count: courses.length,
    courses: courses
  });
} catch (err) {
  return JSON.stringify({ success: false, error: err.message });
}

