const COURSES_API = 'https://6a7db27df8b2ed99ca4ea916.mockapi.io/electronicsapi/courses_batches';
const REG_API = 'https://6a7db27df8b2ed99ca4ea916.mockapi.io/electronicsapi/student_registration';

try {
  const input = typeof query !== 'undefined' ? query : (typeof $input !== 'undefined' && $input.item && $input.item.json ? $input.item.json : {});
  const { studentName, email, mobile, qualification, courseName, batchTime, mode } = input;

  if (!studentName || String(studentName).trim().length < 2) {
    return JSON.stringify({ success: false, error: 'Student name is required (min 2 characters).' });
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRegex.test(String(email).trim())) {
    return JSON.stringify({ success: false, error: 'A valid email address is required.' });
  }

  const cleanMobile = String(mobile || '').replace(/\D/g, '');
  if (!cleanMobile || cleanMobile.length < 10) {
    return JSON.stringify({ success: false, error: 'A valid 10-digit mobile number is required.' });
  }

  if (!qualification || String(qualification).trim().length === 0) {
    return JSON.stringify({ success: false, error: 'Educational qualification is required.' });
  }

  // 1. Verify Course from live Courses API
  const cRes = await fetch(COURSES_API);
  if (!cRes.ok) return JSON.stringify({ success: false, error: 'Courses API unavailable' });
  const allCourses = await cRes.json();

  const targetName = String(courseName || '').toLowerCase().trim();
  const matched = allCourses.find(c => 
    c.courseName && (
      c.courseName.toLowerCase() === targetName ||
      c.courseName.toLowerCase().includes(targetName) ||
      targetName.includes(c.courseName.toLowerCase())
    )
  );

  if (!matched) {
    return JSON.stringify({ success: false, error: 'Course "' + courseName + '" not found in live course database.' });
  }

  if (matched.status && matched.status.toLowerCase() !== 'active') {
    return JSON.stringify({ success: false, error: 'Course is currently inactive.' });
  }

  const seats = Number(matched.seatsAvailable);
  if (isNaN(seats) || seats <= 0) {
    return JSON.stringify({
      success: false,
      seatsFull: true,
      error: 'Unfortunately, this batch is currently full. I can help you find another available batch.'
    });
  }

  // 2. Duplicate Check
  const regRes = await fetch(REG_API);
  if (regRes.ok) {
    const existingRegs = await regRes.json();
    const dup = existingRegs.find(r => {
      const emailMatch = r.email && r.email.toLowerCase().trim() === String(email).toLowerCase().trim();
      const mobileMatch = r.mobile && String(r.mobile).replace(/\D/g, '').slice(-10) === cleanMobile.slice(-10);
      const courseMatch = r.courseName && r.courseName.toLowerCase() === matched.courseName.toLowerCase();
      return (emailMatch || mobileMatch) && courseMatch;
    });

    if (dup) {
      return JSON.stringify({
        success: false,
        isDuplicate: true,
        message: 'You already have a registration for this course.',
        existingRegistration: dup
      });
    }
  }

  // 3. Create Registration with Dynamic Date YYYY-MM-DD
  const today = new Date().toISOString().split('T')[0];
  const payload = {
    studentName: String(studentName).trim(),
    email: String(email).trim().toLowerCase(),
    mobile: cleanMobile.slice(-10),
    courseName: matched.courseName,
    batchTime: batchTime || matched.batchTime,
    registrationDate: today,
    qualification: String(qualification).trim(),
    mode: mode || matched.mode,
    status: 'Registered'
  };

  const postRes = await fetch(REG_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  if (!postRes.ok) {
    return JSON.stringify({ success: false, error: 'Failed to create registration record in database.' });
  }

  const created = await postRes.json();
  return JSON.stringify({
    success: true,
    message: 'Registration successful!',
    registration: {
      id: created.id,
      studentName: created.studentName || payload.studentName,
      courseName: created.courseName || payload.courseName,
      batchTime: created.batchTime || payload.batchTime,
      mode: created.mode || payload.mode,
      qualification: created.qualification || payload.qualification,
      registrationDate: created.registrationDate || payload.registrationDate,
      status: created.status || 'Registered'
    }
  });
} catch (err) {
  return JSON.stringify({ success: false, error: err.message });
}

