// Normalizes input whether it came from Email IMAP Trigger or Webhook Trigger
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};

let senderEmail = json.from || json.senderEmail || json.candidateEmail || 'candidate@example.com';
if (typeof senderEmail === 'object' && senderEmail.value && senderEmail.value[0]) {
  senderEmail = senderEmail.value[0].address || senderEmail.text;
} else if (typeof senderEmail === 'string' && senderEmail.includes('<')) {
  const match = senderEmail.match(/<([^>]+)>/);
  if (match) senderEmail = match[1];
}

let candidateName = json.candidateName || json.name || '';
if (!candidateName && json.from && typeof json.from === 'object' && json.from.value && json.from.value[0]) {
  candidateName = json.from.value[0].name || '';
}

const subject = json.subject || json.emailSubject || 'Job Application - Resume';
const emailBody = json.text || json.textAsHtml || json.body || json.emailBody || 'Please find attached my resume for your consideration.';

// Attachment detection
let attachmentName = 'resume.pdf';
let attachmentData = null;
let attachmentMime = 'application/pdf';

if (binary) {
  const keys = Object.keys(binary);
  if (keys.length > 0) {
    const attKey = keys[0];
    attachmentName = binary[attKey].fileName || binary[attKey].filename || 'resume.pdf';
    attachmentMime = binary[attKey].mimeType || 'application/pdf';
    attachmentData = binary[attKey].data;
  }
}

// Determine Target Role (Strictly Full Stack Developer or Digital Marketing Specialist)
let appliedRole = json.appliedRole || json.role || '';
if (!appliedRole) {
  const combined = (subject + ' ' + emailBody).toLowerCase();
  if (
    combined.includes('digital marketing') ||
    combined.includes('marketing') ||
    combined.includes('seo') ||
    combined.includes('sem') ||
    combined.includes('social media')
  ) {
    appliedRole = 'Digital Marketing Specialist';
  } else {
    appliedRole = 'Full Stack Developer';
  }
}

// If plain text resume provided in webhook payload
let resumeText = json.resumeText || '';
if (!resumeText && !attachmentData) {
  resumeText = emailBody;
}

return {
  json: {
    senderEmail,
    candidateName,
    subject,
    emailBody,
    appliedRole,
    attachmentName,
    attachmentMime,
    hasAttachment: !!attachmentData,
    resumeText: resumeText.slice(0, 8000)
  },
  binary: binary
};

