  const subjectName = body.subjectName || 'Python Programming';
  const sessionType = body.sessionType || 'theory';
  const existingSchedule = body.existingSchedule || body.existingSchedules || [];

  // 4-Way Conflict Check Engine
  let conflictFound = false;
  let conflictType = null;
  let conflictMessage = null;

  for (const entry of existingSchedule) {
    // Check same day and time slot
    if (entry.day === day && entry.slot === slot) {
      // Check 1: Room Conflict
      if (entry.classroom === classroom) {
        conflictFound = true;
        conflictType = 'ROOM_DOUBLE_BOOKED';
        conflictMessage = `Room Collision: ${classroom} is already occupied by ${entry.subjectCode} (${entry.program || 'Cohort'} ${entry.section || ''}) at ${day} ${slot}.`;
        break;
      }
      // Check 2: Faculty Conflict
      if (entry.facultyId === facultyId) {
        conflictFound = true;
        conflictType = 'FACULTY_DOUBLE_BOOKED';
        conflictMessage = `Faculty Collision: ${facultyName} (${facultyId}) is already teaching ${entry.subjectCode} in ${entry.classroom} at ${day} ${slot}.`;
        break;
      }
      // Check 3: Cohort Conflict
      if (entry.program === program && entry.semester === semester && entry.section === section) {
        conflictFound = true;
        conflictType = 'COHORT_OVERLAP';
        conflictMessage = `Cohort Overlap: ${program} Sem ${semester} (${section}) already has ${entry.subjectCode} scheduled at ${day} ${slot}.`;
        break;
      }
    }
  }

  // Check 4: Capacity constraint check
  const targetRoom = ROOMS.find(r => r.id === classroom);
  if (targetRoom && sessionType === 'theory' && targetRoom.capacity < 50) {
    conflictFound = true;
    conflictType = 'CAPACITY_DEFICIT';
    conflictMessage = `Capacity Deficit: ${targetRoom.name} capacity (${targetRoom.capacity}) is too small for full cohort ${section} (60 students).`;
  }

  if (conflictFound) {
    responseData = {
      success: false,
      conflict: true,
      code: conflictType,
      conflictType: conflictType,
      reason: conflictMessage,
      message: conflictMessage,
      timestamp: timestamp
    };
