    responseData = {
      success: true,
      conflict: false,
      action: action,
      slotEntry: {
        id: `SCH-${Date.now()}`,
        program: program,
        semester: semester,
        section: section,
        day: day,
        slot: slot,
        subjectCode: subjectCode,
        subjectName: subjectName,
        facultyId: facultyId,
        facultyName: facultyName,
        classroom: classroom,
        sessionType: sessionType
      },
      message: `Slot successfully scheduled: ${subjectCode} in ${classroom} with ${facultyName} at ${day} ${slot}.`,
      timestamp: timestamp
    };
  }
