    if (domains.some(d => d.includes(studentDomain.toLowerCase()) || studentDomain.toLowerCase().includes(d))) {
      score += 25;
    }
    const hasCapacity = alm.activeMenteesCount < alm.mentorshipCapacity;
    if (hasCapacity) score += 20;
    else score -= 30;

    const finalScore = Math.max(15, Math.min(99, score));
    return {
      alumniId: alm.id,
      fullName: alm.fullName,
      company: alm.company,
      currentDesignation: alm.currentDesignation,
      industry: alm.industry,
      expertiseDomains: alm.expertiseDomains,
      availableSlots: alm.mentorshipCapacity - alm.activeMenteesCount,
      matchScore: finalScore,
      isAvailable: hasCapacity
    };
  });

  matchedMentors.sort((a, b) => b.matchScore - a.matchScore);

